package android.os;public class PowerManager {public static final int PARTIAL_WAKE_LOCK=1;public boolean interactive,fail;public WakeLock latest;public boolean isInteractive(){return interactive;}public WakeLock newWakeLock(int level,String tag){latest=new WakeLock(level,tag,this);return latest;}public static class WakeLock {public final int level;public final String tag;final PowerManager p;public boolean held,referenceCounted=true;public int acquires,releases;public long timeout;WakeLock(int l,String t,PowerManager p){level=l;tag=t;this.p=p;}public void setReferenceCounted(boolean v){referenceCounted=v;}public boolean isHeld(){return held;}public void acquire(long ms){if(p.fail)throw new SecurityException();held=true;acquires++;timeout=ms;}public void release(){held=false;releases++;}}}
